```dart
import 'package:collection/collection.dart';

List<dynamic> getTopProfitCoins(List<Transaction> transactions) {
  return transactions
      .groupBy((e) => e.coinName)
      .map((key, value) {
        final sum = value.fold(0, (prev, curr) => prev + curr.profit);
        final avg = sum / value.length;
        return {
          'coinName': key,
          'avgProfit': avg,
          'transactions': value,
        };
      })
      .toList()
      .where((element) => element['avgProfit'] != null)
      .sortBy((element) => element['avgProfit'], reverse: true)
      .take(3);
}

List<dynamic> getTopLossCoins(List<Transaction> transactions) {
  return transactions
      .groupBy((e) => e.coinName)
      .map((key, value) {
        final sum = value.fold(0, (prev, curr) => prev + curr.profit);
        final avg = sum / value.length;
        return {
          'coinName': key,
          'avgLoss': avg,
          'transactions': value,
        };
      })
      .toList()
      .where((element) => element['avgLoss'] != null)
      .sortBy((element) => element['avgLoss'], reverse: false)
      .take(3);
}
```

