Here's some sample code to get you started:
```cpp
#include <QApplication>
#include <QMatrix>
#include <QPixmap>
#include <QLabel>
#include <QSlider>

class Matrix {
public:
    Matrix(int rows, int columns) : rows_(rows), columns_(columns) {
        data_.resize(rows * columns);
    }

    void set(int row, int column, int value) {
        data_[row * columns + column] = value;
    }

    int get(int row, int column) const {
        return data_[row * columns + column];
    }

private:
    int rows_;
    int columns_;
    std::vector<int> data_;
};

class Bitmap {
public:
    Bitmap(const Matrix& matrix, int width, int height) : width_(width), height_(height) {
        pixmap_.create(width, height, QPixmap::Format_RGB32);
        update();
    }

    void update() {
        for (int i = 0; i < width_; ++i) {
            for (int j = 0; j < height_; ++j) {
                int index = i * width_ + j;
                int value = matrix.get(index / width_, index % width_);
                pixmap_.setPixel(index, qRgb(value, value, value));
            }
        }
    }

    QPixmap& getPixmap() {
        return pixmap_;
    }

private:
    int width_;
    int height_;
    QPixmap pixmap_;
};

