Here's a C++ program that implements the described functionality:

```cpp
#include <iostream>
#include <string>
#include <sstream>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, num3;
    int count;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);
    iss >> num1 >> num2;

    if (num1 < 0 || num2 < 0) {
        cerr << "Error: Both integers must be non-negative." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> count;

    if (count <= 0) {
        cerr << "Error: The number of sequence elements must be a positive integer." << endl;
        return 1;
    }

    num3 = fibonacci(count, num1, num2);

    cout << "Fibonacci sequence (" << count << " elements): ";
    for (int i = 0; i < count; ++i) {
        cout << num3 << (i < count - 1 ? ", " : "");
        num3 = num1 + num2;
        num1 = num2;
        num2 = num3;
    }
    cout << endl;

    return 0;
}
```

