Here's a C++ program implementing the Bubble Sort algorithm to sort the integers in ascending order:

```cpp
#include <iostream>
#include <vector>

void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
            }
        }
    }
}

int main() {
    std::vector<int> arr = {5, 2, 9, 1, 5, 6};
    bubbleSort(arr);
    for (auto num : arr) {
        std::cout << num << " ";
    }
    return 0;
}
```

