public static double CalculateTotalCost(double carPrice, double clothesPrice, double bookPrice)
{
    double totalClothesAndBookPrice = clothesPrice + bookPrice;

    // Check if the car price is at least double the combined price of the clothes and the book
    if (carPrice < totalClothesAndBookPrice * 2)
    {
        // Adjust the car price to meet the constraint
        carPrice = totalClothesAndBookPrice * 2;
    }

    // Calculate the total cost of the purchase
    double totalCost = carPrice + totalClothesAndBookPrice;

    return totalCost;
}
