        colorPrefLabel.text = "Color preference: \(colorPref)"
    }

    @IBAction func reviewButtonTapped(_ sender: Any) {
        review = "Great product!"
        reviewLabel.text = "Review: \(review)"
    }

    func generateStatement() -> String {
