Here's a simple Go program that parses a struct in a Go source file and generates an AVRO schema from it. The generated schema will be written to a file named "struct.avsc".

```go
package main

import (
	"fmt"
	"io/ioutil"
	"log"
	"reflect"
	"strings"

	"github.com/apache/avro/v2/avro"
	"github.com/apache/avro/v2/data"
)

func main() {
	if len(argv) != 3 {
		log.Fatal("Usage: ./generate_avro_schema <go_source_file> <struct_name>")
	}

	goSourceFile := argv[1]
	structName := argv[2]

	content, err := ioutil.ReadFile(goSourceFile)
	if err != nil {
		log.Fatal(err)
	}

	tokens := strings.Split(string(content), "\n")
	var fields []avro.Field

	for _, token := range tokens {
		if strings.HasPrefix(token, "type") {
			continue
		}

		parts := strings.SplitN(token, " ", 2)
		if len(parts) != 2 {
			continue
		}

		fieldName := parts[0]
		fieldType := parts[1]

		fields = append(fields, avro.Field{
			Name:  fieldName,
			Type:  avro.Type_fromString(fieldType),
		})
	}

	schema := avro.Schema{
		Name:  structName,
		Fields: fields,
	}

	err = ioutil.WriteFile("struct.avsc", schema.ToString(), 0644)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("AVRO schema generated for %s\n", structName)
}
```

