```R
# Load necessary libraries
library(xml2)
library(tidyverse)
library(lubridate)

# Define functions to extract data from each source
extract_xml <- function(file_path) {
  xml_data <- read_xml(file_path)
  data <- xml_data %>%
    xml_nodes("item") %>%
    lapply(function(x) {
      title <- x %>%
        xml_attr("title")
      date <- x %>%
        xml_attr("date")
      return(list(title = title, date = date))
    }) %>%
    unlist()
  return(data)
}

extract_csv <- function(file_path) {
  csv_data <- read_csv(file_path)
  data <- csv_data %>%
    select(title, date) %>%
    as.data.frame()
  return(data)
}

extract_json <- function(file_path) {
  json_data <- read_json(file_path)
  data <- json_data %>%
    lapply(function(x) {
      title <- x$title
      date <- x$date
      return(list(title = title, date = date))
    }) %>%
    unlist()
  return(data)
}

# Extract data from each source and combine into a single data frame
xml_data <- extract_xml("xml_file.xml")
csv_data <- extract_csv("csv_file.csv")
json_data <- extract_json("json_file.json")

data <- rbind(xml_data, csv_data, json_data)

# Organize data into a coherent timeline
data %>%
  arrange(date) %>%
  group_by(date) %>%
  summarize(title = paste(unique(title), collapse = ", ")) -> timeline

