To retrieve the username from the JWT token in ASP.NET C# WebAPI, you can follow these steps:

1. Install the `Microsoft.IdentityModel.Tokens` package using NuGet.
2. In your WebAPI project, create a new class that will handle the JWT token validation and retrieval of the username.
3. In the class, define a method that takes the JWT token as a parameter and returns the username.
4. Use the `Microsoft.IdentityModel.Tokens.JwtSecurityTokenHandler` class to validate the JWT token and extract the username from the token's claims.
5. Return the username as a string.
6. In your WebAPI controllers, you can inject the instance of the class that handles the JWT token validation and retrieval of the username and use it to retrieve the username from the JWT token in your API actions.

Here is an example of how you can implement this:
```csharp
using Microsoft.IdentityModel.Tokens;
using System.Security.Claims;
using System.Text;

public class JwtTokenHandler
{
    private readonly string _secretKey;

    public JwtTokenHandler(string secretKey)
    {
        _secretKey = secretKey;
    }

    public string GetUsernameFromJwtToken(string jwtToken)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.ASCII.Parse(_secretKey);
        var token = tokenHandler.ReadJwtToken(jwtToken, new TokenValidationParameters
        {
            ValidateIssuer = false,
            ValidateAudience = false,
            IssuerSigningKey = key,
            ClockSkew = TimeSpan.Zero
        });

        var username = token.Claims.FirstOrDefault(c => c.Type == "username")?.Value;
        return username;
    }
}

public class MyController : ControllerBase
{
    private readonly JwtTokenHandler _jwtTokenHandler;

    public MyController(JwtTokenHandler jwtTokenHandler)
    {
        _jwtTokenHandler = jwtTokenHandler;
    }

