```tsx
import React, { useState } from 'react';
import { useCombobox } from 'downshift';

interface Email {
  id: number;
  email: string;
}

const searchEmails = (prefix: string): Promise<Email[]> => {
  // Implement your email search logic here
  // For now, let's just return some sample data
  return Promise.resolve([
    { id: 1, email: 'john@example.com' },
    { id: 2, email: 'jane@example.com' },
    { id: 3, email: 'bob@example.com' },
  ]);
};

const EmailInput: React.FC = () => {
  const [emails, setEmails] = useState([]);
  const { isOpen, selectedItem, getMenuProps, getComboboxProps, getItemProps } = useCombobox({
    items: emails,
    getItemPredictor: (item: Email) => item.email,
    onSelect: (selectedItem: Email) => {
      setEmails([selectedItem]);
    },
  });

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const prefix = event.target.value;
    searchEmails(prefix).then((newEmails) => {
      setEmails(newEmails);
    });
  };

  return (
    <div>
      <input
        {...getComboboxProps()}
        value={selectedItem?.email || ''}
        onChange={handleInputChange}
        placeholder="Search emails..."
      />
      {isOpen && (
        <ul {...getMenuProps()}>
          {emails.map((email) => (
            <li {...getItemProps({ item: email })} key={email.id}>
              {email.email}
            </li>
          ))}

