setPlanets(generateRandomPlanets(5, 35));
```

Here's a simple React utility to remove widows in your text:

```javascript
import React, { useState } from 'react';

const RemoveWidows = ({ text }) => {
  const [formattedText, setFormattedText] = useState(text);

  const handleRemoveWidows = () => {
    setFormattedText(text.replace(/(\w+)\b(?=\s)/g, '$1 '));
  };

  return (
    <div>
      <button onClick={handleRemoveWidows}>Remove Widows</button>
      <p>{formattedText}</p>
    </div>
  );
};

export default RemoveWidows;
```

