// redis.js
class RedisClient {
  constructor() {
    this.client = require('redis').createClient();

    this.client.on('error', (err) => {
      console.error('Error with Redis Client:', err);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    try {
      const result = await this.client.get(key);
      return result;
    } catch (err) {
      console.error('Error getting from Redis:', err);
      throw err;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
    } catch (err) {
      console.error('Error setting to Redis:', err);
      throw err;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
    } catch (err) {
      console.error('Error deleting from Redis:', err);
      throw err;
    }
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

